insert into public.angelcare360_settings_definitions(school_id,configuration_key,label,description,family_key,family_label,value_type,default_value_json,scope_label,approval_class,state) select v.school_id,v.configuration_key,v.label,v.description,v.family_key,v.family_label,v.value_type,v.default_value_json,v.scope_label,v.approval_class,v.state from public.angelcare360_schools s cross join lateral (values (s.id,'institution.identity','Identité de l’établissement','Nom, logo autorisé, coordonnées et présentation visible.','general','Identité de l’établissement','object','{}'::jsonb,'Établissement','Direction','active'),(s.id,'institution.locale','Formats & localisation','Langue, fuseau horaire, formats de date et début de semaine.','general','Localisation et formats','object','{"language":"fr","timezone":"Africa/Casablanca","currency":"Dh"}'::jsonb,'Établissement','Administration','active'),(s.id,'academic.period_template','Modèle de périodes','Organisation attendue des trimestres ou semestres.','academic','Calendrier de fonctionnement','object','{}'::jsonb,'Année scolaire','Direction','active'),(s.id,'capacity.reservation_duration','Durée de réservation d’une place','Durée pendant laquelle une place reste bloquée avant confirmation.','capacity','Classes et capacités','duration','{"days":7}'::jsonb,'Établissement','Administration','active'),(s.id,'curriculum.required_domains','Domaines pédagogiques obligatoires','Domaines attendus pour chaque niveau.','curriculum','Programme pédagogique','multi','[]'::jsonb,'Réseau','Coordination pédagogique','active'),(s.id,'assignment.workload_threshold','Seuil de charge pédagogique','Seuil déclenchant une vérification avant une nouvelle affectation.','assignments','Équipe et affectations','number','{"hours_per_week":24}'::jsonb,'Établissement','Direction','active'),(s.id,'access.review_frequency','Fréquence de revue des accès','Période entre deux revues formelles des accès sensibles.','access','Utilisateurs et accès','duration','{"days":90}'::jsonb,'Réseau','Direction','active'),(s.id,'notifications.quiet_hours','Heures sans notifications','Plage pendant laquelle les notifications non urgentes sont différées.','notifications','Notifications','object','{"from":"20:00","to":"07:00"}'::jsonb,'Établissement','Administration','active'),(s.id,'documents.communication_footer','Signature des communications','Pied de page utilisé dans les communications autorisées.','templates','Documents','text','{"text":""}'::jsonb,'Établissement','Administration','active'),(s.id,'integrations.messaging','Messagerie institutionnelle','Configuration gouvernée du connecteur de messagerie.','integrations','Intégrations','object','{}'::jsonb,'Établissement','Direction','active')) as v(school_id,configuration_key,label,description,family_key,family_label,value_type,default_value_json,scope_label,approval_class,state) on conflict(school_id,configuration_key) do nothing;
insert into public.angelcare360_settings_template_variables(school_id,variable_key,label,value_type,sensitive,state) select v.school_id,v.variable_key,v.label,v.value_type,v.sensitive,v.state from public.angelcare360_schools s cross join lateral (values (s.id,'child_name','Prénom de l’enfant','text',false,'active'),(s.id,'parent_name','Nom du parent','text',false,'active'),(s.id,'institution_name','Nom de l’établissement','text',false,'active'),(s.id,'class_name','Classe','text',false,'active'),(s.id,'due_date','Date d’échéance','text',false,'active'),(s.id,'outstanding_amount','Montant restant','text',true,'active'),(s.id,'appointment_date','Date du rendez-vous','text',false,'active'),(s.id,'school_contact','Contact de l’établissement','text',false,'active')) as v(school_id,variable_key,label,value_type,sensitive,state) on conflict(school_id,variable_key) do nothing;
