begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare360_settings_definitions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,label text not null,description text not null,family_key text not null,family_label text not null,value_type text not null,default_value_json jsonb not null default '{}'::jsonb,validation_json jsonb not null default '{}'::jsonb,allowed_values_json jsonb not null default '[]'::jsonb,scope_label text not null default 'Établissement',inheritance_label text not null default 'Valeur de l’établissement',approval_class text not null default 'Administration',entitlement_key text,can_override boolean not null default true,requires_impact_preview boolean not null default true,state text not null default 'active',owner_id uuid references public.app_users(id) on delete set null,owner_label text,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,configuration_key));
create table if not exists public.angelcare360_settings_schema_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,version_number integer not null,schema_json jsonb not null default '{}'::jsonb,state text not null default 'draft',effective_from timestamptz,effective_to timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),unique(school_id,configuration_key,version_number));
create table if not exists public.angelcare360_settings_scope_bindings(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,scope_type text not null,scope_id uuid,scope_label text not null,inherits_from_id uuid references public.angelcare360_settings_scope_bindings(id) on delete set null,override_allowed boolean not null default true,effective_from timestamptz,effective_to timestamptz,state text not null default 'active',created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_local_variations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,configuration_label text not null,institution_id uuid,institution_label text,site_id uuid,site_label text,parent_value_json jsonb not null default '{}'::jsonb,local_value_json jsonb not null default '{}'::jsonb,reason text not null,starts_at timestamptz,ends_at timestamptz,review_at timestamptz,state text not null default 'draft',approval_label text,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,ended_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_change_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,title text not null,reason text not null,current_value_json jsonb not null default '{}'::jsonb,proposed_value_json jsonb not null default '{}'::jsonb,scope_json jsonb not null default '{}'::jsonb,target_at timestamptz,state text not null default 'requested',requester_id uuid references public.app_users(id) on delete set null,reviewer_id uuid references public.app_users(id) on delete set null,decision_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_releases(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,release_code text not null,name text not null,purpose text not null,scope_label text not null default 'Établissement',target_at timestamptz,state text not null default 'draft',item_count integer not null default 0,successful_count integer not null default 0,failed_count integer not null default 0,rollback_version_id uuid references public.angelcare360_governance_configuration_versions(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,activated_by uuid references public.app_users(id) on delete set null,activated_at timestamptz,completed_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,release_code));
create table if not exists public.angelcare360_settings_release_items(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,release_id uuid not null references public.angelcare360_settings_releases(id) on delete cascade,configuration_key text not null,changeset_id uuid references public.angelcare360_governance_configuration_changesets(id) on delete set null,label text not null,sequence_number integer not null default 1,state text not null default 'included',created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_release_outcomes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,release_id uuid not null references public.angelcare360_settings_releases(id) on delete cascade,release_item_id uuid not null references public.angelcare360_settings_release_items(id) on delete cascade,configuration_key text not null,state text not null default 'pending',message text,attempt_count integer not null default 0,executed_by uuid references public.app_users(id) on delete set null,executed_at timestamptz,result_json jsonb not null default '{}'::jsonb,unique(release_id,release_item_id));
create table if not exists public.angelcare360_settings_rollback_runs(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,source_release_id uuid references public.angelcare360_settings_releases(id) on delete set null,target_version_id uuid references public.angelcare360_governance_configuration_versions(id) on delete set null,scope_json jsonb not null default '{}'::jsonb,reason text not null,state text not null default 'pending',requested_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,executed_by uuid references public.app_users(id) on delete set null,executed_at timestamptz,result_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_emergency_events(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,configuration_key text not null,reason text not null,scope_json jsonb not null default '{}'::jsonb,proposed_value_json jsonb not null default '{}'::jsonb,starts_at timestamptz not null,ends_at timestamptz,state text not null default 'pending',requested_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,activated_at timestamptz,reviewed_by uuid references public.app_users(id) on delete set null,reviewed_at timestamptz,ended_at timestamptz,rollback_plan_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_template_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,template_key text not null,label text not null,purpose text not null,content_text text not null default '',channels_json jsonb not null default '[]'::jsonb,languages_json jsonb not null default '["fr"]'::jsonb,variable_keys_json jsonb not null default '[]'::jsonb,scope_label text not null default 'Établissement',version_number integer not null,state text not null default 'draft',last_validated_at timestamptz,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,replaces_version_id uuid references public.angelcare360_settings_template_versions(id) on delete set null,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,template_key,version_number));
create table if not exists public.angelcare360_settings_template_variables(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,variable_key text not null,label text not null,description text,value_type text not null default 'text',sensitive boolean not null default false,allowed_channels_json jsonb not null default '[]'::jsonb,state text not null default 'active',created_at timestamptz not null default now(),unique(school_id,variable_key));
create table if not exists public.angelcare360_settings_notification_policy_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,policy_key text not null,label text not null,event_key text not null,channel_key text not null,recipient_policy_json jsonb not null default '{}'::jsonb,cadence_json jsonb not null default '{}'::jsonb,quiet_hours_json jsonb not null default '{}'::jsonb,fallback_json jsonb not null default '{}'::jsonb,version_number integer not null,state text not null default 'draft',effective_from timestamptz,effective_to timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,policy_key,version_number));
create table if not exists public.angelcare360_settings_integration_configurations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,integration_key text not null,label text not null,purpose text not null,entitlement_state text not null default 'included',connection_state text not null default 'disconnected',affected_modules_json jsonb not null default '[]'::jsonb,data_scope_label text not null default 'Périmètre limité',credential_reference text,last_verified_at timestamptz,credential_review_at timestamptz,issue_count integer not null default 0,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,integration_key));
create table if not exists public.angelcare360_settings_conflicts(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,fingerprint text not null,configuration_key text,configuration_id uuid,configuration_label text,title text not null,detail text not null,consequence text,severity text not null default 'high',state text not null default 'open',owner_id uuid references public.app_users(id) on delete set null,owner_label text,due_at timestamptz,resolved_at timestamptz,created_at timestamptz not null default now(),unique(school_id,fingerprint));
create table if not exists public.angelcare360_settings_drift_findings(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,fingerprint text not null,configuration_key text,configuration_id uuid,configuration_label text,title text not null,detail text not null,consequence text,severity text not null default 'warning',expected_signature text,actual_signature text,state text not null default 'open',owner_label text,due_at timestamptz,resolved_at timestamptz,detected_at timestamptz not null default now(),unique(school_id,fingerprint));
create table if not exists public.angelcare360_settings_issues(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,fingerprint text not null,category text not null,title text not null,detail text not null,consequence text,entity_kind text,entity_id uuid,entity_label text,severity text not null default 'warning',state text not null default 'open',owner_id uuid references public.app_users(id) on delete set null,owner_label text,due_at timestamptz,recommended_action_key text,recommended_action_label text,resolution_reason text,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,fingerprint));
create table if not exists public.angelcare360_settings_tasks(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,entity_type text not null,entity_id uuid,title text not null,detail text,owner_id uuid references public.app_users(id) on delete set null,owner_label text,due_at timestamptz,state text not null default 'open',completed_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_notes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,entity_type text not null,entity_id uuid,note text not null,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
