create table if not exists public.angelcare360_settings_evidence_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,entity_type text not null,entity_id uuid,request_label text not null,reason text,state text not null default 'requested',requested_by uuid references public.app_users(id) on delete set null,due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_topup_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,capability_key text not null,quantity integer not null default 1,package_version_id uuid,state text not null default 'requested',source_context jsonb not null default '{}'::jsonb,requested_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_history(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,event_key text not null,label text not null,entity_type text not null,entity_id uuid,detail text,actor_id uuid references public.app_users(id) on delete set null,actor_label text,metadata_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.angelcare360_settings_action_receipts(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,action_key text not null,idempotency_key text not null,entity_type text,entity_id uuid,message text,result_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(school_id,action_key,idempotency_key));
create index if not exists angelcare360_settings_definitions_school_idx on public.angelcare360_settings_definitions(school_id);
