do $$ declare t text; begin foreach t in array array['angelcare360_settings_definitions','angelcare360_settings_schema_versions','angelcare360_settings_scope_bindings','angelcare360_settings_local_variations','angelcare360_settings_change_requests','angelcare360_settings_releases','angelcare360_settings_release_items','angelcare360_settings_release_outcomes','angelcare360_settings_rollback_runs','angelcare360_settings_emergency_events','angelcare360_settings_template_versions','angelcare360_settings_template_variables','angelcare360_settings_notification_policy_versions','angelcare360_settings_integration_configurations','angelcare360_settings_conflicts','angelcare360_settings_drift_findings','angelcare360_settings_issues','angelcare360_settings_tasks','angelcare360_settings_notes','angelcare360_settings_approval_reviews','angelcare360_settings_evidence_requests','angelcare360_settings_topup_requests','angelcare360_settings_history','angelcare360_settings_action_receipts'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke insert,update,delete on public.%I from anon,authenticated',t); end loop; end $$;
on conflict(operation_key) do update set route_path=excluded.route_path,feature_key=excluded.feature_key,operation_name=excluded.operation_name,permission_key=excluded.permission_key,audit_event=excluded.audit_event,mutation_endpoints=excluded.mutation_endpoints,source_confidence=excluded.source_confidence,status=excluded.status,updated_at=now();
commit;
